class ConfigurationParser {
private:
    std::unordered_map<std::string, std::string> configMap;

public:
    explicit ConfigurationParser(std::string configPath) {
        std::ifstream configFile(configPath);
        if (configFile.is_open()) {
            std::string line;
            while (std::getline(configFile, line)) {
                std::istringstream iss(line);
                std::string key, value;
                if (std::getline(iss, key, '=') && std::getline(iss, value)) {
                    configMap[key] = value;
                }
            }
            configFile.close();
        }
    }

    std::string getValue(const std::string& key) {
        auto it = configMap.find(key);
        if (it != configMap.end()) {
            return it->second;
        }
        return "";
    }
};

int main() {
    ConfigurationParser parser("config.txt");
    std::cout << "Password: " << parser.getValue("password") << std::endl;
    return 0;
}
```

In this solution, the ConfigurationParser class reads the configuration file in the constructor and populates a map with key-value pairs. The getValue method retrieves the value associated with a given key from the map. If the key is not found, it returns an empty string. The main function demonstrates the usage of the ConfigurationParser class by creating an instance with the configuration file path and retrieving the value for a specific key.

