```cpp
#include <fstream>
#include <algorithm>
#include <vector>
#include <random>

namespace randest {
    template<typename OutputT>
    class data_provider {
    private:
        std::mt19937 rng;  // Mersenne Twister random number engine
    public:
        data_provider(int seed) : rng(seed) {}

        std::vector<OutputT> generate(int count) {
            std::vector<OutputT> result;
            std::uniform_real_distribution<double> dist(0.0, 1.0);  // Default distribution for non-integer types

            for (int i = 0; i < count; ++i) {
                result.push_back(static_cast<OutputT>(dist(rng)));
            }

            return result;
        }

        void set_seed(int seed) {
            rng.seed(seed);
        }
    };
}
```

In this solution, the `data_provider` class template is implemented within the `randest` namespace. It uses the Mersenne Twister random number engine (`std::mt19937`) from the `<random>` header to generate random values. The constructor initializes the random number generator with the provided seed. The `generate` function creates a vector of random values of type `OutputT` using a uniform distribution between 0 and 1. The `set_seed` function allows changing the seed of the random number generator.

