    MPI_Init(&argc, &argv);
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);

    if (argc != 2) {
        if (rank == 0) {
            std::cerr << "Usage: " << argv[0] << " <num_processes>" << std::endl;
        }
        MPI_Finalize();
        return 1;
    }

    int num_processes = std::stoi(argv[1]);

    if (num_processes < 1) {
        if (rank == 0) {
            std::cerr << "Number of processes should be at least 1." << std::endl;
        }
        MPI_Finalize();
        return 1;
    }

    if (rank == 0) {
        // Read input matrices A and B from files
        std::vector<std::vector<int>> A(SZ, std::vector<int>(SZ));
        std::vector<std::vector<int>> B(SZ, std::vector<int>(SZ));
        // Read A and B from files into A and B matrices
        // ...

        // Broadcast input matrices A and B to all processes
        MPI_Bcast(&A[0][0], SZ * SZ, MPI_INT, 0, MPI_COMM_WORLD);
        MPI_Bcast(&B[0][0], SZ * SZ, MPI_INT, 0, MPI_COMM_WORLD);
    }

    // Calculate the assigned rows of matrix C - matrix multiplication
    int num_rows_per_process = SZ / num_processes;
    std::vector<std::vector<int>> C(num_rows_per_process, std::vector<int>(SZ, 0));
    for (int i = rank * num_rows_per_process; i < (rank + 1) * num_rows_per_process; i++) {
        for (int j = 0; j < SZ; j++) {
            for (int k = 0; k < SZ; k++) {
                C[i - rank * num_rows_per_process][j] += A[i][k] * B[k][j];
            }
        }
    }

    // Gather the calculated rows of matrix C from all processes
    std::vector<std::vector<int>> gathered_C(SZ, std::vector<int>(SZ));
    MPI_Gather(&C[0][0], num_rows_per_process * SZ, MPI_INT, &gathered_C[0][0], num_rows_per_process * SZ, MPI_INT, 0, MPI_COMM_WORLD);

    if (rank == 0) {
        // Write the resulting matrix C to an output file
        std::ofstream outfile("result_matrix.txt");
        for (int i = 0; i < SZ; i++) {
            for (int j = 0; j < SZ; j++) {
                outfile << gathered_C[i][j] << " ";
            }
            outfile << std::endl;
        }
        outfile.close();
    }

    MPI_Finalize();
    return 0;
}
