#include <regex>

std::vector<std::string> extractNestedElements(const std::string& namespaceStr) {
    std::vector<std::string> nestedElements;

    // Regular expression to match nested namespaces and classes
    std::regex nestedRegex("\\b" + namespaceStr + "::(\\w+)");

