```cpp
cv::Vec3f bilinearInterpolation(const cv::Mat_<cv::Vec3f>& image, int ix, int iy, float ry) {
    int ix_1 = std::min(ix + 1, image.cols - 1);
    int iy_1 = std::min(iy + 1, image.rows - 1);

    const cv::Vec3f& cxy = image.at<cv::Vec3f>(iy, ix);
    const cv::Vec3f& cx_1y = image.at<cv::Vec3f>(iy, ix_1);
    const cv::Vec3f& cx_1y_1 = image.at<cv::Vec3f>(iy_1, ix_1);
    const cv::Vec3f& cxy_1 = image.at<cv::Vec3f>(iy_1, ix);

    cv::Vec3f cx = (1.0f - ry) * cxy + ry * cxy_1;
    cv::Vec3f cx_1 = (1.0f - ry) * cx_1y + ry * cx_1y_1;

    return (1.0f - static_cast<float>(ix - ix_1)) * cx + static_cast<float>(ix - ix_1) * cx_1;
}
```

The `bilinearInterpolation` function first calculates the integer coordinates of the neighboring pixels `(ix_1, iy)` and `(ix, iy_1)`. Then, it retrieves the color values of the four neighboring pixels and uses them to perform bilinear interpolation to calculate the color value at the fractional pixel position `(ix, iy)`. Finally, it returns the interpolated color value.

