        std::cerr << "Error opening zip file" << std::endl;
        return 1;
    }

    int numFiles = zip_get_num_files(archive);
    for (int i = 0; i < numFiles; i++) {
        struct zip_stat fileStat;
        if (zip_stat_index(archive, i, 0, &fileStat) == 0) {
            struct zip_file* file = zip_fopen_index(archive, i, 0);
            if (file) {
                std::string extractPath = extractDir + fileStat.name;
                FILE* outFile = fopen(extractPath.c_str(), "wb");
                if (outFile) {
                    char* buffer = new char[fileStat.size];
                    zip_fread(file, buffer, fileStat.size);
                    fwrite(buffer, 1, fileStat.size, outFile);
                    delete[] buffer;
                    fclose(outFile);
                } else {
                    std::cerr << "Error creating file: " << extractPath << std::endl;
                }
                zip_fclose(file);
            } else {
                std::cerr << "Error opening file in zip" << std::endl;
            }
        } else {
