#include <vector>
#include <string>

std::vector<int> countInlineConst(const std::vector<std::string>& codeSnippets) {
    std::vector<int> counts;
    for (const std::string& snippet : codeSnippets) {
        int count = 0;
        size_t pos = 0;
        while ((pos = snippet.find("inline const", pos)) != std::string::npos) {
            count++;
            pos += 12; // Move past the found pattern to search for the next occurrence
        }
        counts.push_back(count);
    }
    return counts;
}
