1. `CircularBuffer(int capacity)`: A constructor that initializes the circular buffer with the given capacity.
2. `void write(int value)`: A method that writes a new value to the circular buffer. If the buffer is full, the oldest value should be overwritten.
3. `int read()`: A method that reads the oldest value from the circular buffer and removes it from the buffer. If the buffer is empty, return -1.

You should use the provided code snippet as a starting point and implement the missing functionalities to create a fully functional circular buffer.

```cpp
#include <iostream>
#include <vector>

class CircularBuffer {
private:
    std::vector<int> buffer;
    int capacity;
    int head;
    int tail;
    bool full;

public:
    CircularBuffer(int capacity) : buffer(capacity), capacity(capacity), head(0), tail(0), full(false) {}

    void write(int value) {
        buffer[tail] = value;
        tail = (tail + 1) % capacity;
        if (tail == head) {
            head = (head + 1) % capacity;
            full = true;
        }
    }

    int read() {
        if (head == tail && !full) {
            return -1; // Buffer is empty
        }
        int value = buffer[head];
        head = (head + 1) % capacity;
        full = false;
        return value;
    }
};

