#include "arcane/ISubDomain.h"
#include "arcane/StringDictionary.h"
#include "arcane/VariableCollection.h"
#include "arcane/IVariableSynchronizer.h"

double calculateTotalVolume(IMesh* mesh, const std::string& itemGroupName) {
    IItemFamily* itemFamily = mesh->itemFamily(itemGroupName);
    ItemGroup itemGroup = itemFamily->itemGroup(itemGroupName);

    double totalVolume = 0.0;
    IVariable* volumeVariable = mesh->findVariable("Volume");

    for (ItemEnumerator itemEnumerator = itemGroup.enumerator(); itemEnumerator.hasNext(); ++itemEnumerator) {
        Item item = *itemEnumerator;
        totalVolume += volumeVariable->asReal(item);
    }

    return totalVolume;
}
