MACGrid calculateScaledVelocityField(const FlagGrid &flags, const MACGrid &v, Real tauMin, Real tauMax, Real scaleFromManta) {
  MACGrid scaledVelocityField(v);  // Initialize the scaled velocity field with the original velocity field

  for (int i = 0; i < scaledVelocityField.u.size().x; ++i) {
    for (int j = 0; j < scaledVelocityField.u.size().y; ++j) {
      for (int k = 0; k < scaledVelocityField.u.size().z; ++k) {
        if (flags(i, j, k) == FLUID) {
          scaledVelocityField.u(i, j, k) *= scaleFromManta;  // Scale u component
          scaledVelocityField.v(i, j, k) *= scaleFromManta;  // Scale v component
          scaledVelocityField.w(i, j, k) *= scaleFromManta;  // Scale w component
        }
      }
    }
  }

  return scaledVelocityField;
}
