                const auto& currEvent = events[i];
                double distance = std::sqrt(std::pow(currEvent.x - prevEvent.x, 2) + std::pow(currEvent.y - prevEvent.y, 2));
                totalDistance += distance;
            }
            return totalDistance;
        }
    };
}
