std::vector<std::vector<int>> applyKernel(const std::vector<std::vector<int>>& inputImage, const std::vector<std::vector<int>>& kernel) {
    int rows = inputImage.size();
    int cols = inputImage[0].size();
    std::vector<std::vector<int>> outputImage(rows, std::vector<int>(cols, 0));

    for (int i = 1; i < rows - 1; ++i) {
        for (int j = 1; j < cols - 1; ++j) {
            int sum = 0;
            for (int k = -1; k <= 1; ++k) {
                for (int l = -1; l <= 1; ++l) {
                    sum += inputImage[i + k][j + l] * kernel[k + 1][l + 1];
                }
            }
            outputImage[i][j] = sum;
        }
    }
    return outputImage;
}
