```cpp
#include <iostream>
#include <unordered_map>

class Slider {
private:
    std::string mName;
    double mValue;

public:
    Slider(const std::string& name) : mName(name), mValue(0.0) {}

    const std::string& getName() const {
        return mName;
    }

    double getValue() const {
        return mValue;
    }

    void setValue(double value) {
        mValue = value;
    }
};

class SliderSet {
private:
    std::unordered_map<std::string, Slider*> mSliders;

public:
    Slider* createSlider(const std::string& name) {
        Slider* newSlider = new Slider(name);
        mSliders[name] = newSlider;
        return newSlider;
    }

    Slider* getSlider(const std::string& name) {
        auto it = mSliders.find(name);
        if (it != mSliders.end()) {
            return it->second;
        }
        return nullptr;
    }

    void setSliderValue(const std::string& name, double value) {
        Slider* slider = getSlider(name);
        if (slider != nullptr) {
            slider->setValue(value);
        }
    }

    void deleteSlider(const std::string& name) {
        auto it = mSliders.find(name);
        if (it != mSliders.end()) {
            delete it->second;
            mSliders.erase(it);
        }
    }

    ~SliderSet() {
        for (auto& pair : mSliders) {
            delete pair.second;
        }
    }
};

int main() {
    SliderSet sliders;
    sliders.createSlider("feedback");
    sliders.createSlider("time");
    sliders.createSlider("gain");

    Slider* feedbackSlider = sliders.getSlider("feedback");
    if (feedbackSlider != nullptr) {
