class Context {
    std::vector<Device> _devs;
    int _id;

public:
    Context(int id) : _id(id) {}

    bool create(EDeviceType type) {
        // Find the maximum ID of existing devices
        int maxId = 0;
        for (const auto& dev : _devs) {
            maxId = std::max(maxId, dev._id);
        }

        // Create a new device with a unique ID
