    std::for_each(vec2.begin(), vec2.end(), [](int& val) { val = std::rand() % 100; });

    // Perform distributed addition of the vectors
    hpx::parallel::transform(exec, vec1.begin(), vec1.end(), vec2.begin(), result.begin(),
        [](int a, int b) { return a + b; });

