class ExceptionTranslator {
public:
    template <typename Func>
    void translate(Func func) {
        try {
            func();
        } catch (const std::exception& ex) {
            auto it = exceptionMap.find(typeid(ex).name());
            if (it != exceptionMap.end()) {
                throw it->second();
            } else {
