```cpp
void addToSSTable(int targetLevel, const std::string& targetDir, const std::string& key, const std::string& val, std::vector<std::vector<ssTable>>& levelArray, std::vector<int>& nextLabel, uint64_t& tmpTimeStamp, uint64_t& tmpSize, std::vector<std::pair<std::string, std::string>>& tmp) {
    std::string fileName = targetDir + '/' + std::to_string(nextLabel[targetLevel]) + ".sst";
    levelArray[targetLevel].emplace_back(ssTable::genTable(fileName, tmpTimeStamp, tmp));
    ++nextLabel[targetLevel];
    tmp.clear();
    tmpTimeStamp = 0;
    tmpSize = 0;

    tmp.emplace_back(key, val);
    tmpSize += val.size() + sizeof(uint64_t) + sizeof(uint32_t);
    if (tmpTimeStamp == 0) {
        tmpTimeStamp = getCurrentTimeStamp();  // Assuming a function getCurrentTimeStamp() returns the current timestamp.
    }

    // Sort the temporary vector of key-value pairs by key
    std::sort(tmp.begin(), tmp.end(), [](const std::pair<std::string, std::string>& a, const std::pair<std::string, std::string>& b) {
        return a.first < b.first;
    });

    // Add the temporary key-value pairs to the SSTable
    for (const auto& pair : tmp) {
        levelArray[targetLevel].back().addKeyValuePair(pair.first, pair.second);
    }

    // Update the metadata of the SSTable
    levelArray[targetLevel].back().updateMetadata(tmpTimeStamp, tmpSize);
}
```

