typedef std::function<void(int, const std::vector<int>&)> MODULE_EVENT_FUNCTOR;

class EventSystem {
private:
    std::map<int, std::set<MODULE_EVENT_FUNCTOR>> mEventHandlers;

public:
    void registerHandler(int eventID, MODULE_EVENT_FUNCTOR handler) {
        // Add the handler function to the set of handlers for the specified event ID
        mEventHandlers[eventID].insert(handler);
    }

    void unregisterHandler(int eventID, MODULE_EVENT_FUNCTOR handler) {
        // Remove the handler function from the set of handlers for the specified event ID
        mEventHandlers[eventID].erase(handler);
    }

    void dispatchEvent(int eventID, const std::vector<int>& valueList) {
        // Invoke all the handler functions registered for the specified event ID
        auto handlers = mEventHandlers[eventID];
        for (const auto& handler : handlers) {
            handler(eventID, valueList);
        }
    }
};

int main() {
    EventSystem eventSystem;

    // Register handler functions for event IDs
    eventSystem.registerHandler(1, [](int eventID, const std::vector<int>& valueList) {
        std::cout << "Event ID " << eventID << " handled with values: ";
        for (const auto& value : valueList) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    });

    eventSystem.registerHandler(2, [](int eventID, const std::vector<int>& valueList) {
        std::cout << "Event ID " << eventID << " handled with values: ";
        for (const auto& value : valueList) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    });

