```cpp
#include <iostream>

class Node {
public:
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};

class Stack {
private:
    Node* topNode;

public:
    // Default constructor
    Stack() : topNode(nullptr) {}

    // Destructor
    ~Stack() {
        while (topNode != nullptr) {
            Node* temp = topNode;
            topNode = topNode->next;
            delete temp;
        }
    }

    void push(int val) {
        Node* newNode = new Node(val);
        newNode->next = topNode;
        topNode = newNode;
    }

    int pop() {
        if (topNode == nullptr) {
            std::cerr << "Error: Stack is empty" << std::endl;
            return -1; // Assuming -1 as an error value
        }
        int val = topNode->data;
        Node* temp = topNode;
        topNode = topNode->next;
        delete temp;
        return val;
    }

    int top() {
        if (topNode == nullptr) {
            std::cerr << "Error: Stack is empty" << std::endl;
            return -1; // Assuming -1 as an error value
        }
        return topNode->data;
    }

    bool isEmpty() {
        return topNode == nullptr;
    }
};

int main() {
    Stack stack;
    stack.push(5);
    stack.push(10);
    std::cout << stack.top() << std::endl; // Output: 10
    std::cout << stack.pop() << std::endl; // Output: 10
    std::cout << stack.top() << std::endl; // Output: 5
    std::cout << std::boolalpha << stack.isEmpty() << std::endl; // Output: false
    std::cout << stack.pop() << std::endl; // Output: 5
    std::cout << std::boolalpha << stack.isEmpty() << std::endl; // Output: true
    return 0;
}
