template <typename T>
class Optional {
private:
    bool hasValue;
    T storedValue;

public:
    Optional() : hasValue(false) {}

    Optional(const T& value) : hasValue(true), storedValue(value) {}

    bool has_value() const {
        return hasValue;
    }

    T value() const {
        if (!hasValue) {
            throw std::logic_error("Optional does not contain a value");
        }
        return storedValue;
    }

    T value_or(const T& default_value) const {
