#include <string>
#include <utility>

bool validateBuffer(const std::vector<std::pair<std::string, std::pair<const char*, size_t>>& index, const std::vector<char>& buffer) {
  for (const auto& item : index) {
    const char* subRangeStart = item.second.first;
    size_t subRangeSize = item.second.second;
    const char* bufferStart = buffer.data();
    const char* bufferEnd = bufferStart + buffer.size();

    if (subRangeStart < bufferStart || subRangeStart + subRangeSize > bufferEnd) {
