You are given the following information:
- The scene consists of spheres defined as in the code snippet.
- The camera is located at a fixed position and orientation.
- The ray's origin and direction are provided to the function.
- The Phong reflection model parameters: ambient, diffuse, and specular coefficients, as well as the shininess exponent.

Implement the function `calculateRayColor` that takes the ray's origin and direction, and returns the color of the ray after intersecting with the scene, considering the Phong reflection model.

```cpp
struct Vec {
    double x, y, z;
    Vec(double x_ = 0, double y_ = 0, double z_ = 0) : x(x_), y(y_), z(z_) {}
};

struct Sphere {
    double radius;
    Vec position, emission, color;
    enum Material { DIFF, SPEC, REFR } material;
    Sphere(double radius_, const Vec& position_, const Vec& emission_, const Vec& color_, Material material_)
        : radius(radius_), position(position_), emission(emission_), color(color_), material(material_) {}
};

inline double clamp(double x) { return x < 0 ? 0 : x > 1 ? 1 : x; }

Vec calculateRayColor(const Vec& origin, const Vec& direction, const std::vector<Sphere>& spheres,
                      const Vec& ambientColor, const Vec& lightPosition, const Vec& lightColor,
                      double diffuseCoeff, double specularCoeff, double shininess);
```

```cpp
#include <vector>
#include <cmath>

Vec calculateRayColor(const Vec& origin, const Vec& direction, const std::vector<Sphere>& spheres,
                      const Vec& ambientColor, const Vec& lightPosition, const Vec& lightColor,
                      double diffuseCoeff, double specularCoeff, double shininess) {
    // Find the closest intersection point with a sphere
    double tNear = INFINITY;
    const Sphere* hitSphere = nullptr;
    for (const auto& sphere : spheres) {
        Vec oc = origin - sphere.position;
        double b = oc.x * direction.x + oc.y * direction.y + oc.z * direction.z;
        double c = oc.x * oc.x + oc.y * oc.y + oc.z * oc.z - sphere.radius * sphere.radius;
        double discriminant = b * b - c;
        if (discriminant > 0) {
            double t = -b - std::sqrt(discriminant);
            if (t > 0 && t < tNear) {
                tNear = t;
                hitSphere = &sphere;
            }
        }
    }

    // If no intersection, return black color
    if (!hitSphere) {
        return Vec(0, 0, 0);
    }

    // Calculate the intersection point and normal
    Vec intersectionPoint = origin + direction * tNear;
    Vec normal = (intersectionPoint - hitSphere->position).normalize();

    // Calculate the ambient, diffuse, and specular components
    Vec ambient = hitSphere->color * ambientColor;
    Vec toLight = (lightPosition - intersectionPoint).normalize();
    double diffuse = std::max(0.0, normal.dot(toLight)) * diffuseCoeff;
    Vec diffuseColor = hitSphere->color * lightColor * diffuse;
    Vec reflection = normal * 2 * normal.dot(toLight) - toLight;
    double specular = std::pow(std::max(0.0, reflection.dot(-direction)), shininess) * specularCoeff;
    Vec specularColor = lightColor * specular;

    // Calculate the final color using the Phong reflection model
    Vec finalColor = ambient + diffuseColor + specularColor;

    return finalColor;
}
```

