class U8String {
private:
    char* data;

public:
    // Default constructor
    U8String() : data(new char[1]) {
        data[0] = '\0';
    }

    // Constructor with C-style string argument
    U8String(const char* str) {
        int len = strlen(str);
        data = new char[len + 1];
        strcpy(data, str);
    }

    // Destructor
    ~U8String() {
        delete[] data;
    }

    // Method to get the length of the string
    int length() const {
        return strlen(data);
    }

    // Method to get a substring
    U8String substr(int start, int len) const {
        return U8String(data + start, len);
    }

    // Method to append another U8String
    void append(const U8String& other) {
        int len1 = strlen(data);
        int len2 = other.length();
        char* newData = new char[len1 + len2 + 1];
        strcpy(newData, data);
        strcpy(newData + len1, other.data);
        delete[] data;
        data = newData;
    }

    // Method to access character at a specific index
    char at(int index) const {
        return data[index];
    }
};

int main() {
