#include <CL/cl.h>
#include <vector>
#include <stdexcept>

int sumOnGPU(const std::vector<int>& inputArray) {
    if (inputArray.empty()) {
        throw std::invalid_argument("empty input array");
    }

    cl_int error;
    cl_platform_id platform;
    clGetPlatformIDs(1, &platform, nullptr);

    cl_device_id device;
    clGetDeviceIDs(platform, CL_DEVICE_TYPE_GPU, 1, &device, nullptr);

    cl_context context = clCreateContext(nullptr, 1, &device, nullptr, nullptr, &error);
    cl_command_queue queue = clCreateCommandQueue(context, device, 0, &error);

    cl_mem inputBuffer = clCreateBuffer(context, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, sizeof(int) * inputArray.size(), const_cast<int*>(inputArray.data()), &error);
    cl_mem outputBuffer = clCreateBuffer(context, CL_MEM_WRITE_ONLY, sizeof(int), nullptr, &error);

    const char* kernelSource = R"(
        __kernel void sum(__global const int* input, __global int* output) {
            int sum = 0;
            for (int i = 0; i < get_global_size(0); i++) {
                sum += input[i];
            }
            *output = sum;
        }
    )";

    cl_program program = clCreateProgramWithSource(context, 1, &kernelSource, nullptr, &error);
    clBuildProgram(program, 1, &device, nullptr, nullptr, nullptr);
    cl_kernel kernel = clCreateKernel(program, "sum", &error);

    clSetKernelArg(kernel, 0, sizeof(cl_mem), &inputBuffer);
    clSetKernelArg(kernel, 1, sizeof(cl_mem), &outputBuffer);

    size_t globalSize = inputArray.size();
    clEnqueueNDRangeKernel(queue, kernel, 1, nullptr, &globalSize, nullptr, 0, nullptr, nullptr);

    int result;
    clEnqueueReadBuffer(queue, outputBuffer, CL_TRUE, 0, sizeof(int), &result, 0, nullptr, nullptr);

    clReleaseMemObject(inputBuffer);
    clReleaseMemObject(outputBuffer);
    clReleaseKernel(kernel);
    clReleaseProgram(program);
    clReleaseCommandQueue(queue);
    clReleaseContext(context);

    return result;
}
```

