#include <opencv2/opencv.hpp>

class ImageProcessor {
    int height;
    int width;
    cv::Mat mat;
    double maxMSE;
    double maxEpoch;
    int bottom_padding;
    int top_padding;
    int left_padding;
    int right_padding;
public:
    ImageProcessor(int h, int w, const cv::Mat& m, double max_mse, double max_epoch, int bottom_pad, int top_pad, int left_pad, int right_pad)
        : height(h), width(w), mat(m), maxMSE(max_mse), maxEpoch(max_epoch), bottom_padding(bottom_pad), top_padding(top_pad), left_padding(left_pad), right_padding(right_pad) {}

    void padImage() {
        cv::copyMakeBorder(mat, mat, top_padding, bottom_padding, left_padding, right_padding, cv::BORDER_CONSTANT, cv::Scalar(0));
    }

    double calculateMSE(const cv::Mat& original, const cv::Mat& padded) {
        cv::Mat diff;
        cv::absdiff(original, padded, diff);
        diff.convertTo(diff, CV_32F);
        diff = diff.mul(diff);
        double mse = cv::mean(diff)[0];
        return mse;
    }

    void trainModel() {
        int epoch = 0;
        double mse = 0.0;
        do {
            padImage();
            mse = calculateMSE(mat, paddedMat);
            epoch++;
        } while (epoch < maxEpoch && mse <= maxMSE);
    }
};
