    double error = 0.0;
    double norm = 0.0;
    for (unsigned long long k = 0; k < h0.size(); k++) {
        error += std::pow(h0[k] - h[k], 2);
        norm += std::pow(h[k], 2);
    }
    if (norm > 0) {
        error = std::sqrt(error / norm);
    }
    std::string cautionMessage = (error > 1e-12) ? "Caution! error=" + std::to_string(error) : "";
    return std::make_pair(error, cautionMessage);
}

int main() {
    std::vector<double> h0 = {1.0, 2.0, 3.0};
    std::vector<double> h = {1.1, 2.1, 3.1};
    auto result = calculateError(h0, h);
    std::cout << "Normalized error: " << result.first << std::endl;
    if (!result.second.empty()) {
        std::cerr << result.second << std::endl;
    }
    return 0;
}
