public:
    void addUser(const std::string& name, const std::string& password)
    {
        data::karluser user;
        user.name = name;
        user.password_salt = generateSalt();
        user.password_hashed = hashPassword(password, user.password_salt);
        // Store user in the system
        // ...
    }

    bool verifyPassword(const std::string& name, const std::string& password)
    {
        // Retrieve user from the system
        data::karluser user = getUserByName(name);
        if (user.name.empty()) {
            return false; // User not found
        }
        // Hash input password using the retrieved salt
        data::token hashed_input = hashPassword(password, user.password_salt);
        // Compare with stored hashed password
        return hashed_input.value == user.password_hashed.value;
    }

private:
    data::token generateSalt()
    {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<int> dis(0, 255);
        std::stringstream ss;
        for (int i = 0; i < 16; ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << dis(gen);
