#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

// Base class for statistical accumulators
class Accumulator {
public:
    virtual double calculate(const std::vector<double>& data) = 0;
    virtual ~Accumulator() {}
};

// Accumulator for mean calculation
class AccumulatorMean : public Accumulator {
public:
    double calculate(const std::vector<double>& data) override {
        double sum = 0.0;
        for (double val : data) {
            sum += val;
        }
        return sum / data.size();
    }
};

// Accumulator for median calculation
class AccumulatorMedian : public Accumulator {
public:
    double calculate(const std::vector<double>& data) override {
        std::vector<double> sortedData = data;
        std::sort(sortedData.begin(), sortedData.end());
        size_t size = sortedData.size();
        if (size % 2 == 0) {
            return (sortedData[size / 2 - 1] + sortedData[size / 2]) / 2.0;
        } else {
            return sortedData[size / 2];
        }
    }
};

// Accumulator for minimum calculation
class AccumulatorMinimum : public Accumulator {
public:
    double calculate(const std::vector<double>& data) override {
        return *std::min_element(data.begin(), data.end());
    }
};

// Accumulator for maximum calculation
class AccumulatorMaximum : public Accumulator {
public:
    double calculate(const std::vector<double>& data) override {
        return *std::max_element(data.begin(), data.end());
    }
};

// Accumulator for quantile calculation
class AccumulatorQuantile : public Accumulator {
private:
    double quantileValue;

public:
    AccumulatorQuantile(double q) : quantileValue(q) {}

    double calculate(const std::vector<double>& data) override {
        std::vector<double> sortedData = data;
        std::sort(sortedData.begin(), sortedData.end());
        size_t n = sortedData.size();
        double pos = quantileValue * (n + 1);
        if (pos < 1) {
            return sortedData[0];
        } else if (pos >= n) {
            return sortedData[n - 1];
        } else {
            size_t lowerPos = static_cast<size_t>(pos);
            double fraction = pos - lowerPos;
            return sortedData[lowerPos - 1] + fraction * (sortedData[lowerPos] - sortedData[lowerPos - 1]);
        }
    }
};

// Example usage
int main() {
    std::vector<double> data = {3.5, 2.0, 7.1, 4.8, 5.2};

    std::string summary_type = "mean";  // Example summary type
    Accumulator* accum;

    if (summary_type == "mean")
        accum = new AccumulatorMean();
    else if (summary_type == "median")
        accum = new AccumulatorMedian();
    else if (summary_type == "min")
        accum = new AccumulatorMinimum();
    else if (summary_type == "max")
        accum = new AccumulatorMaximum();
    else if (summary_type.find("quantile") != std::string::npos) {
        std::vector<std::string> tokens;
        // Implement logic to extract quantile value from summary_type and initialize AccumulatorQuantile
        double quantileValue = 0.5;  // Example quantile value
        accum = new AccumulatorQuantile(quantileValue);
    }

    std::cout << "Summary: " << accum->calculate(data) << std::endl;

    delete accum;  // Remember to free memory
    return 0;
}
