        if (state.y < gridSize - 1) {
            state.y++;
        }
    }

    // Move the robot left in the grid
    void MoveLeft(ROCKSAMPLE_STATE& state) {
        if (state.x > 0) {
            state.x--;
        }
    }

    // Move the robot right in the grid
    void MoveRight(ROCKSAMPLE_STATE& state, int gridSize) {
        if (state.x < gridSize - 1) {
            state.x++;
        }
    }

    // Collect a rock sample at the current location if available
    void CollectSample(ROCKSAMPLE_STATE& state, std::vector<std::vector<bool>>& grid) {
        if (grid[state.x][state.y]) {
            state.rockSamples.push_back(true);
            grid[state.x][state.y] = false;  // Mark the collected sample as unavailable
        }
    }

    // Display the current state of the robot and the grid
    void DisplayState(const ROCKSAMPLE_STATE& state, std::ostream& ostr, const std::vector<std::vector<bool>>& grid) const {
        ostr << std::endl;
        for (int x = 0; x < grid.size() + 2; x++)
            ostr << "# ";
        ostr << std::endl;

        for (int y = 0; y < grid[0].size(); y++) {
            ostr << "# ";
