vector<int> findSubarray(vector<int> &arr, int targetSum) {
    int n = arr.size();
    int start = 0, curSum = arr[0];
    bool flag = true;

    for (int i = 1; i <= n; i++) {
        while (curSum > targetSum && start < i - 1) {
            curSum -= arr[start];
            start++;
        }

        if (curSum == targetSum) {
            cout << start + 1 << " " << i << endl;
            flag = false;
            break;
        }

        if (i < n)
            curSum += arr[i];
    }

    if (flag) {
        cout << "No subarray found";
    }

    return {start + 1, i};
}

int main() {
