    std::string command;
    std::string name = "user"; // Default prompt

    while (true) {
        std::cout << name << "@" << currentDirectory << "~> ";
        std::getline(std::cin, command);

        if (command.compare("exit -h") == 0) {
            // Handle exit command
            break;
        }
        else if (command.compare("prompt") == 0) {
            // Handle prompt command
            name;
        }
        else if (strstr(command.c_str(), "prompt") != NULL) {
            // Handle custom prompt command
            name = "#" + command.erase(0, 7) + "~>"; 
        }
        else if (command.compare(0, 7, "create ") == 0) {
            // Handle create command
            createFile(command.substr(7));
        }
        else if (command.compare(0, 7, "delete ") == 0) {
            // Handle delete command
            deleteFile(command.substr(7));
        }
        else if (command.compare("list") == 0) {
            // Handle list command
            listFiles();
        }
        else {
            std::cout << "Error: Unknown command" << std::endl;
        }
    }

    return 0;
}
