#include <vector>
#include <unordered_map>

double expectedGamesToWin(const std::vector<int>& results, int k) {
    int n = results.size();
    std::unordered_map<int, int> count;
    int sum = 0;
    int consecutiveWins = 0;

    for (int i = 0; i < n; i++) {
        sum += results[i];
        if (i >= k) {
            sum -= results[i - k];
        }
        if (sum >= k) {
            consecutiveWins++;
        }
        count[consecutiveWins]++;
    }

    double expectedValue = 0.0;
    for (auto& [wins, frequency] : count) {
        expectedValue += (double)frequency * wins / n;
    }

    return expectedValue;
}
