    for (size_t p = 0; p < input.size() - 1; p++) {
        if ((input[p] - '0') + (input[p + 1] - '0') == 9) {
            ++count;
        } else {
            if (count % 2 == 0) {
                total *= (1 + (count + 1) / 2);
            }
            count = 0;
        }
