#include <iostream>

namespace rtt_cdi_analytic {

template <typename T>
class CustomSharedPtr {
public:
    // Constructor
    CustomSharedPtr(T* ptr) : m_ptr(ptr), m_refCount(new size_t(1)) {}

    // Copy constructor
    CustomSharedPtr(const CustomSharedPtr<T>& other) : m_ptr(other.m_ptr), m_refCount(other.m_refCount) {
        (*m_refCount)++;
    }

    // Assignment operator
    CustomSharedPtr<T>& operator=(const CustomSharedPtr<T>& other) {
        if (this != &other) {
            // Decrement the reference count of the current object
            decrementRefCount();
            m_ptr = other.m_ptr;
            m_refCount = other.m_refCount;
            (*m_refCount)++;
        }
        return *this;
    }

    // Destructor
    ~CustomSharedPtr() {
        decrementRefCount();
    }

    T& operator*() const {
        return *m_ptr;
    }

    T* operator->() const {
        return m_ptr;
    }

private:
    T* m_ptr;
    size_t* m_refCount;

    void decrementRefCount() {
        (*m_refCount)--;
        if (*m_refCount == 0) {
            delete m_ptr;
            delete m_refCount;
        }
    }
};

