#include <iostream>
#include <stack>
#include <string>

class BasicCalculator {
public:
    int calculate(std::string s) {
        std::stack<char> ops;
        std::stack<int> values;
        int num = 0;
        char op = '+';

        for (char c : s) {
            if (std::isdigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '+' || c == '-') {
                evaluate(ops, values, op, num);
                num = 0;
                op = c;
            }
        }
        evaluate(ops, values, op, num);

        return accumulate(values);
    }

private:
    void evaluate(std::stack<char>& ops, std::stack<int>& values, char op, int num) {
        if (op == '+') {
            values.push(num);
        } else if (op == '-') {
            values.push(-num);
        }
    }

    int accumulate(std::stack<int>& values) {
        int result = 0;
        while (!values.empty()) {
            result += values.top();
            values.pop();
        }
        return result;
    }
};

int main() {
    BasicCalculator calculator;
    std::string expression = "3+2-1+5-4";
    std::cout << "Result: " << calculator.calculate(expression) << std::endl;
    return 0;
}
