```cpp
#include <vector>
#include <string>
#include <algorithm>

class Solution
{
public:
    std::vector<int> shortestToChar(std::string &s, char c)
    {
        std::vector<int> res(s.size(), s.size());  // Initialize the result array with maximum possible distance
        int pos = -s.size();  // Initialize the position of the last occurrence of character c

        // Traverse the string from left to right
        for (int i = 0; i < s.size(); ++i)
        {
            if (s[i] == c)
                pos = i;  // Update the position of the last occurrence of character c

            res[i] = std::min(res[i], std::abs(i - pos));  // Update the distance to character c
        }

        // Traverse the string from right to left
        for (int i = s.size() - 1; i >= 0; --i)
        {
            if (s[i] == c)
                pos = i;  // Update the position of the last occurrence of character c

            res[i] = std::min(res[i], std::abs(i - pos));  // Update the distance to character c
        }

        return res;
    }
};
```

The `shortestToChar` function initializes the result array with the maximum possible distance and the position of the last occurrence of character `c` with a negative value. It then traverses the string from left to right, updating the distance to character `c` at each position. After that, it traverses the string from right to left, updating the distance to character `c` again. Finally, it returns the result array containing the shortest distances to the given character. This solution has a time complexity of O(n), where n is the length of the input string.

