#include <iostream>
#include <utility>

int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

std::pair<int, int> rational_cast(double value) {
    const double EPSILON = 1e-9;  // Small value to compare floating-point numbers

    int sign = (value < 0) ? -1 : 1;
    value = std::abs(value);

    int wholePart = static_cast<int>(value);
    double fractionalPart = value - wholePart;

    int denominator = 1;
    while (std::abs(fractionalPart - static_cast<double>(static_cast<int>(fractionalPart))) > EPSILON) {
        fractionalPart *= 10;
        denominator *= 10;
    }

    int numerator = static_cast<int>(fractionalPart) + wholePart * denominator;

    int commonDivisor = gcd(numerator, denominator);
    numerator /= commonDivisor;
    denominator /= commonDivisor;

    return std::make_pair(sign * numerator, denominator);
}

int main() {
    double input = 3.75;
    std::pair<int, int> result = rational_cast(input);
    std::cout << "Rational representation of " << input << " is: " << result.first << "/" << result.second << std::endl;
    return 0;
}
```

The `rational_cast` function first extracts the whole and fractional parts of the input floating-point number. It then converts the fractional part to an equivalent fraction by multiplying it by 10 until it becomes an integer. The resulting numerator and denominator are then simplified by finding their greatest common divisor using the `gcd` function. Finally, the function returns the simplified rational number as a pair of integers.

