using namespace std;

using LL = long long;

vector<int> simulateAdd(int x, int initialAns, LL initialY, int initialSmall, vector<pair<int, LL>> operations) {
    int ans = initialAns;
    LL y = initialY;
    int small = initialSmall;

    for (auto op : operations) {
        int i = op.first;
        LL t = op.second;

        ans += (t << i - x) - t;
        y -= t << i - x;
        small += (t << i) - (t << i - x);
    }

    return {ans, static_cast<int>(y), small};
}

int main() {
    int x = 2;
    int initialAns = 0;
    LL initialY = 10;
    int initialSmall = 5;
    vector<pair<int, LL>> operations = {{3, 4}, {2, 3}, {4, 5}};

    vector<int> result = simulateAdd(x, initialAns, initialY, initialSmall, operations);

    cout << "Final values: ";
    for (int val : result) {
        cout << val << " ";
    }
    cout << endl;

    return 0;
}
