The `add` function should perform element-wise addition of the two matrices and return the resulting matrix. If the matrices have different dimensions, the function should return an empty matrix.

You are given the following code snippet as an example:

```cpp
full_matrix<int> a = {
    {3, 0, 0},
    {5, 1, 1}
};

full_matrix<int> b = {
    {1, 0, 1},
    {1, 2, 1},
    {1, 1, 0}
};

full_matrix<int> expected = {
    {4, 0, 1},
    {6, 3, 2},
    {0, 0, 0}
};

full_matrix<int> result = a.add(b);
```

Implement the `add` function in the `full_matrix` class to solve this problem.

```cpp
#include <iostream>
#include <vector>

template <typename T>
class full_matrix {
private:
    std::vector<std::vector<T>> matrix;

public:
    full_matrix(const std::initializer_list<std::initializer_list<T>>& list) {
        for (const auto& row : list) {
            matrix.emplace_back(row);
        }
    }

    full_matrix add(const full_matrix& other) const {
        if (matrix.size() != other.matrix.size() || matrix[0].size() != other.matrix[0].size()) {
            return {};  // Return an empty matrix if dimensions are different
        }

        full_matrix result;
        for (size_t i = 0; i < matrix.size(); ++i) {
            std::vector<T> row;
            for (size_t j = 0; j < matrix[i].size(); ++j) {
                row.push_back(matrix[i][j] + other.matrix[i][j]);
            }
            result.matrix.push_back(row);
        }
        return result;
    }

    void print() const {
        for (const auto& row : matrix) {
            for (const auto& elem : row) {
                std::cout << elem << " ";
            }
            std::cout << std::endl;
        }
    }
};

int main() {
    full_matrix<int> a = {
        {3, 0, 0},
        {5, 1, 1}
    };

    full_matrix<int> b = {
        {1, 0, 1},
        {1, 2, 1},
        {1, 1, 0}
    };

    full_matrix<int> expected = {
        {4, 0, 1},
        {6, 3, 2},
        {0, 0, 0}
    };

    full_matrix<int> result = a.add(b);
    result.print();  // Output the result matrix
    return 0;
}
