// Function to calculate the greatest common divisor (GCD) using Euclidean algorithm
int gcd(int x, int y) {
    while (y != 0) {
        int temp = y;
        y = x % y;
        x = temp;
    }
    return x;
}

// Function to calculate the least common multiple (LCM) using the GCD
int lcm(int x, int y) {
    return x * y / gcd(x, y);
