#include <iostream>
#include <vector>
#include <set>

class DFA {
private:
    std::vector<char> alphabet;
    std::set<int> states;
    int initialState;
    std::set<int> finalStates;
    std::vector<std::vector<int>> transitionFunction;

public:
    DFA(const std::vector<char>& alph, const std::set<int>& sts, int init, const std::set<int>& finals, const std::vector<std::vector<int>>& trans) 
        : alphabet(alph), states(sts), initialState(init), finalStates(finals), transitionFunction(trans) {}

    bool isDFA() {
        for (int state : states) {
            std::set<char> seen;
            for (char symbol : alphabet) {
                int nextState = transitionFunction[state][symbol - 'a'];
                if (seen.find(symbol) != seen.end() || nextState < 0 || nextState >= states.size()) {
                    return false;
                }
                seen.insert(symbol);
            }
        }
        return true;
    }

    void showDFA() {
        if (!isDFA()) {
            std::cout << "The finite automaton is not deterministic" << std::endl;
            return;
        }
        std::cout << "Alphabet: ";
        for (char symbol : alphabet) {
            std::cout << symbol << " ";
        }
        std::cout << std::endl;

        std::cout << "States: ";
        for (int state : states) {
            std::cout << state << " ";
        }
        std::cout << std::endl;

        std::cout << "Initial State: " << initialState << std::endl;

        std::cout << "Final States: ";
        for (int state : finalStates) {
            std::cout << state << " ";
        }
        std::cout << std::endl;

        std::cout << "Transition Function:" << std::endl;
        for (int i = 0; i < states.size(); ++i) {
            for (char symbol : alphabet) {
                std::cout << "δ(" << i << ", " << symbol << ") = " << transitionFunction[i][symbol - 'a'] << std::endl;
            }
        }
    }
};

int main() {
    std::vector<char> alphabet = {'a', 'b'};
    std::set<int> states = {0, 1, 2};
    int initialState = 0;
    std::set<int> finalStates = {2};
    std::vector<std::vector<int>> transitionFunction = {{1, 2}, {0, 2}, {2, 2}};

    DFA dfa(alphabet, states, initialState, finalStates, transitionFunction);
    dfa.showDFA();

    if (dfa.isDFA()) {
        std::cout << "The finite automaton is deterministic" << std::endl;
    } else {
        std::cout << "The finite automaton is not deterministic" << std::endl;
    }

    return 0;
}
```

