class Tweak;  // Forward declaration

class NodeWindow {
public:
    void addObserver(Tweak* observer) {
        observers.push_back(observer);
    }

    void removeObserver(Tweak* observer) {
        observers.erase(std::remove(observers.begin(), observers.end(), observer), observers.end());
    }

    void notifyObservers() {
        for (Tweak* observer : observers) {
            observer->onChange();
        }
    }

    // Simulated state change triggering notification to observers
    void changeState() {
