template <typename Range>
class SafeIndirectAdaptor {
public:
    SafeIndirectAdaptor() {}

    SafeIndirectAdaptor(Range&& range) : range(std::forward<Range>(range)) {}

    template <typename R>
    friend SafeIndirectAdaptor<R> operator|(R&& range, SafeIndirectAdaptor) {
        return SafeIndirectAdaptor<R>(std::forward<R>(range));
    }

    Range apply() {
        return range | boost::adaptors::indirected | boost::adaptors::indirect;
    }

private:
    Range range;
};

