    vec.push_back(std::make_unique<int>(10));
    vec.push_back(std::make_unique<int>(20));

    SafeIndirectAdaptor<std::vector<std::unique_ptr<int>>> adaptor(vec);

    auto result = adaptor.apply();

    for (const auto& val : result) {
        std::cout << *val << " ";
    }

    return 0;
}
