    Leaderboard(int capacity) : capacity(capacity) {}

    void AddScore(int score, std::string playerName) {
        if (scores.size() < capacity) {
            scores.push_back({playerName, score});
            std::sort(scores.begin(), scores.end(), [](const PlayerScore& a, const PlayerScore& b) {
                return a.score > b.score;
            });
        } else {
            if (score > scores.back().score) {
                scores.back() = {playerName, score};
                std::sort(scores.begin(), scores.end(), [](const PlayerScore& a, const PlayerScore& b) {
                    return a.score > b.score;
                });
            }
        }
    }

    std::vector<std::pair<std::string, int>> GetTopScores(int count) {
        std::vector<std::pair<std::string, int>> topScores;
        for (int i = 0; i < std::min(count, static_cast<int>(scores.size())); ++i) {
            topScores.push_back({scores[i].name, scores[i].score});
        }
        return topScores;
    }

    void Reset() {
        scores.clear();
    }
