#include <iostream>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define PORTNUM 3425
#define BUFSIZE 256

int main(int argc, char** argv)
{
	if (argc < 3)
	{
		std::cout << "need IP address as 1 argument and WORD as 2 argument\n";
		return 1;
	}

	const char* ipAddr = argv[1];
	const char* word = argv[2];

	int sockfd = socket(AF_INET, SOCK_STREAM, 0);
	if (sockfd < 0) {
		std::cerr << "Error: Failed to create socket\n";
		return 1;
	}

	struct sockaddr_in serverAddr;
	serverAddr.sin_family = AF_INET;
	serverAddr.sin_port = htons(PORTNUM);
	inet_pton(AF_INET, ipAddr, &serverAddr.sin_addr);

	if (connect(sockfd, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
		std::cerr << "Error: Connection failed\n";
		close(sockfd);
		return 1;
	}

	if (send(sockfd, word, strlen(word), 0) < 0) {
		std::cerr << "Error: Failed to send message\n";
		close(sockfd);
		return 1;
	}

	char buffer[BUFSIZE] = {0};
	int bytesReceived = recv(sockfd, buffer, BUFSIZE, 0);
	if (bytesReceived < 0) {
		std::cerr << "Error: Failed to receive response\n";
		close(sockfd);
		return 1;
	}

	std::cout << "Received response from server: " << buffer << std::endl;

	close(sockfd);
	return 0;
}
```

