#include <cstddef>
#include <stdexcept>
#include <memory>

template <typename T, size_t N>
class RingBuf {
public:
    RingBuf() : buffer(new T[N]), head(0), tail(0), size(0) {}

    void push_back(const T& value) {
        if (size == N) {
            head = (head + 1) % N;  // Overwrite the oldest element
        } else {
            size++;
        }
        buffer[tail] = value;
        tail = (tail + 1) % N;
    }

    void pop_front() {
        if (size == 0) {
            throw std::out_of_range("Buffer is empty");
        }
        head = (head + 1) % N;
        size--;
    }

    size_t size() const {
        return size;
    }

private:
    std::unique_ptr<T[]> buffer;
    size_t head;
    size_t tail;
    size_t size;
};

template <typename T, size_t N>
class DequeRingBuf {
public:
    DequeRingBuf() : head(0), tail(0), size(0) {}

    void push_back(const T& value) {
        if (size == N) {
            head = (head + 1) % N;  // Overwrite the oldest element
        } else {
            size++;
        }
        buffer[tail] = value;
        tail = (tail + 1) % N;
    }

    void pop_front() {
        if (size == 0) {
            throw std::out_of_range("Buffer is empty");
        }
        head = (head + 1) % N;
        size--;
    }

    size_t size() const {
        return size;
    }

private:
    T buffer[N];
    size_t head;
    size_t tail;
    size_t size;
};
```

This solution provides a class template for a circular buffer, supporting the required operations `push_back`, `pop_front`, and `size`. The `RingBuf` class uses a dynamically allocated buffer, while the `DequeRingBuf` class uses a fixed-size array for storage. Both classes handle overwriting the oldest element when the buffer is full and ensure that the test case runs successfully for both types of circular buffers.

