class ArgumentParser {
public:
    void add_flag(const std::string& flag) {
        flags.insert(flag);
    }

    void add_option(const std::string& option, const std::string& description) {
        options[option] = description;
    }

    std::map<std::string, std::string> parse(const std::vector<std::string>& args) {
        std::map<std::string, std::string> parsedOptions;
        for (size_t i = 0; i < args.size(); ++i) {
            if (args[i].find("--") == 0) {
                std::string option = args[i].substr(2);
                if (i + 1 < args.size() && args[i + 1].find("--") != 0) {
                    parsedOptions[option] = args[i + 1];
                    ++i;
                } else {
                    // Handle missing value for option
                    std::cerr << "Error: Missing value for option --" << option << std::endl;
                }
            } else if (args[i].find("-") == 0) {
                std::string option = args[i].substr(1);
                if (i + 1 < args.size() && args[i + 1].find("-") != 0) {
                    parsedOptions[option] = args[i + 1];
                    ++i;
                } else {
                    // Handle missing value for option
                    std::cerr << "Error: Missing value for option -" << option << std::endl;
                }
            } else {
                if (flags.find(args[i]) == flags.end()) {
                    // Handle unknown flag or option
                    std::cerr << "Error: Unknown flag or option " << args[i] << std::endl;
                }
            }
        }
        return parsedOptions;
    }

private:
    std::set<std::string> flags;
    std::map<std::string, std::string> options;
};

int main(int argc, char* argv[]) {
