    parser.add_flag("verbose");
    parser.add_option("output", "Specify the output file");

    std::vector<std::string> args = {"--output", "output.txt", "-v", "input.txt"};
    std::map<std::string, std::string> parsed = parser.parse(args);

    std::cout << "Parsed options:" << std::endl;
    for (const auto& pair : parsed) {
        std::cout << pair.first << " = " << pair.second << std::endl;
    }

    return 0;
}
