void createAndPrintLinkedList(int n){
    struct node* head = new node;
    struct node* temp = head;
    for(int i=1; i<=n; i++){
        temp->id = i;
        if(i != n){
            temp->next = new node;
            temp = temp->next;
        } else {
            temp->next = NULL;
        }
