#include <vector>
#include <cmath>

struct Point {
    double x, y;
};

struct Line {
    Point start, end;
};

bool onSegment(const Point& p, const Point& q, const Point& r) {
    if (q.x <= std::max(p.x, r.x) && q.x >= std::min(p.x, r.x) &&
        q.y <= std::max(p.y, r.y) && q.y >= std::min(p.y, r.y)) {
        return true;
    }
    return false;
}

int orientation(const Point& p, const Point& q, const Point& r) {
    double val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (std::abs(val) < 1e-9) {
        return 0;  // Collinear
    }
    return (val > 0) ? 1 : 2;  // Clockwise or counterclockwise
}

bool doIntersect(const Line& l1, const Line& l2) {
    int o1 = orientation(l1.start, l1.end, l2.start);
    int o2 = orientation(l1.start, l1.end, l2.end);
    int o3 = orientation(l2.start, l2.end, l1.start);
    int o4 = orientation(l2.start, l2.end, l1.end);

    if (o1 != o2 && o3 != o4) {
        return true;
    }

    if (o1 == 0 && onSegment(l1.start, l2.start, l1.end)) {
        return true;
    }

    if (o2 == 0 && onSegment(l1.start, l2.end, l1.end)) {
        return true;
    }

    if (o3 == 0 && onSegment(l2.start, l1.start, l2.end)) {
        return true;
    }

    if (o4 == 0 && onSegment(l2.start, l1.end, l2.end)) {
        return true;
    }

    return false;
}

size_t countSelfIntersections(const std::vector<Point>& polygon) {
    size_t count = 0;
    size_t n = polygon.size();

    for (size_t i = 0; i < n; i++) {
        Line current = {polygon[i], polygon[(i + 1) % n]};
        for (size_t j = i + 1; j < n; j++) {
            Line other = {polygon[j], polygon[(j + 1) % n]};
            if (doIntersect(current, other)) {
                count++;
            }
        }
    }

    return count;
}
```

The `countSelfIntersections` function first defines helper functions to check if a point lies on a line segment, calculate the orientation of three points, and determine if two line segments intersect. Then, it iterates through each pair of line segments in the polygon and checks for intersections, incrementing the count when an intersection is found. Finally, it returns the total count of self-intersection points in the polygon.

You are tasked with implementing a function that calculates the median of a given array of integers. The median of a set of numbers is the middle number when the numbers are ordered from least to greatest. If the set contains an odd number of elements, the median is the middle number. If the set contains an even number of elements, the median is the average of the two middle numbers.

You need to write a C++ function `calculateMedian` that takes in an array of integers and its size as input and returns the median of the array.

Function Signature:
```cpp
int calculateMedian(int arr[], int size);
```

Input:
The function `calculateMedian` takes in two parameters:
- `arr`: an array of integers (1 <= size of array <= 10^5)
- `size`: an integer representing the size of the array (1 <= size <= 10^5)

Output:
The function should return an integer representing the median of the array.

Example:
```cpp
int arr1[] = {3, 1, 2, 5, 4};
int size1 = 5;
// The median of the array {3, 1, 2, 5, 4} is 3, so the function should return 3.

int arr2[] = {10, 8, 5, 3, 2, 12};
int size2 = 6;
// The median of the array {10, 8, 5, 3, 2, 12} is the average of 5 and 8, which is 6.5. Since the median should be an integer, the function should return 6.
```

```cpp
#include <algorithm>

int calculateMedian(int arr[], int size) {
    std::sort(arr, arr + size);  // Sort the array in ascending order

    if (size % 2 == 0) {
        // If the size of the array is even, return the average of the two middle elements
        return (arr[size / 2 - 1] + arr[size / 2]) / 2;
    } else {
        // If the size of the array is odd, return the middle element
        return arr[size / 2];
    }
}
```

