            size_t winnerPos = line.find("Winner");
            std::string winner = line.substr(winnerPos + 7);
            playerWins[winner]++;
        }
    }

    file.close();

    std::cout << "#Rounds         " << numRounds << std::endl;

    if (!playerWins.empty()) {
        auto maxWins = std::max_element(playerWins.begin(), playerWins.end(),
            [](const auto& p1, const auto& p2) { return p1.second < p2.second; });
        std::cout << "Overall Winner: " << maxWins->first << " with " << maxWins->second << " wins." << std::endl;
    } else {
        std::cerr << "No round data found." << std::endl;
    }

    return 0;
}
