#include <queue>
#include <mutex>
#include <condition_variable>
#include <memory>

template <typename T>
class ThreadSafeQueue {
public:
    void push(const T& value) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(value);
        lock.unlock();
        condition.notify_one();
    }

    std::shared_ptr<T> pop() {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !queue.empty(); });
        auto value = std::make_shared<T>(queue.front());
        queue.pop();
        return value;
    }

private:
    std::queue<T> queue;
    std::mutex mutex;
    std::condition_variable condition;
};
```

The `ThreadSafeQueue` class uses a `std::queue` to store elements and ensures thread safety using `std::mutex` and `std::condition_variable`. The `push` method adds a new element to the queue and notifies waiting threads, while the `pop` method blocks until an element is available and then returns the front element. This implementation guarantees thread safety and satisfies the requirements outlined in the problem description.

