#include <iostream>

class DynamicArray {
private:
    int* arr;
    int size;
    int capacity;

    void resize() {
        int newCapacity = capacity * 2;
        int* newArr = new int[newCapacity];
        for (int i = 0; i < size; i++) {
            newArr[i] = arr[i];
        }
        delete[] arr;
        arr = newArr;
        capacity = newCapacity;
    }

public:
    DynamicArray() : arr(new int[2]), size(0), capacity(2) {}

    void add(int element) {
        if (size == capacity) {
            resize();
        }
        arr[size++] = element;
    }

    void remove() {
        if (size > 0) {
            size--;
        }
    }

    int getSize() const {
        return size;
    }

    ~DynamicArray() {
        delete[] arr;
    }
};

