You are given a segment tree implementation in C++ for range queries on an array. The segment tree is represented using a class with the following member functions:

```cpp
ll qrl(ll li, ll ri)
ll qrr(ll li, ll ri)
void clr()
```

Where `ll` is a typedef for a long long integer, and the segment tree has been constructed for an array of integers. The `qrl` function is used to query the minimum value in the range `[li, ri)` in the array, and the `qrr` function is used to query the maximum value in the same range. The `clr` function is used to clear the segment tree.

Your task is to implement the `qrl` and `qrr` functions for the segment tree class.

Write a C++ function to implement the `qrl` and `qrr` functions for the segment tree class. You should assume that the segment tree has already been constructed and is represented by the given class.

```cpp
#include <iostream>
#include <vector>
using namespace std;

typedef long long ll;

class SegmentTree {
private:
    ll l, r, dtr;
    SegmentTree *lc, *rc;

public:
    SegmentTree(ll left, ll right, vector<ll>& arr) {
        l = left;
        r = right;
        if (l == r - 1) {
            dtr = arr[l];
        } else {
            ll m = (l + r) / 2;
            lc = new SegmentTree(l, m, arr);
            rc = new SegmentTree(m, r, arr);
            dtr = min(lc->dtr, rc->dtr);
        }
    }

    ll qrl(ll li, ll ri) {
        if (li >= r || ri <= l) return LLONG_MAX;
        else if (li <= l && ri >= r) return dtr;
        else return min(lc->qrl(li, ri), rc->qrl(li, ri));
    }

    ll qrr(ll li, ll ri) {
        if (li >= r || ri <= l) return LLONG_MIN;
        else if (li <= l && ri >= r) return dtr;
        else return max(lc->qrr(li, ri), rc->qrr(li, ri));
    }

    void clr() {
        if (l == r - 1) {
            dtr = LLONG_MAX;
        } else {
            lc->clr();
            rc->clr();
            dtr = min(lc->dtr, rc->dtr);
        }
    }
};

int main() {
    vector<ll> arr = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
    SegmentTree st(0, arr.size(), arr);

    cout << st.qrl(2, 7) << endl;  // Output: 1
    cout << st.qrr(2, 7) << endl;  // Output: 9

    st.clr();
    cout << st.qrl(2, 7) << endl;  // Output: 9223372036854775807 (LLONG_MAX)
    cout << st.qrr(2, 7) << endl;  // Output: -9223372036854775808 (LLONG_MIN)

    return 0;
}
```

