    std::vector<std::thread> thread_pool;
    std::mutex mtx;
    std::condition_variable cv;
    bool stop_server = false;

    void processRequest(int clientID) {
        // Process the incoming network request for the given clientID
        // Implement the request processing logic here
        std::cout << "Processing request for client " << clientID << std::endl;
    }

    void handleRequests() {
        while (!stop_server) {
            // Wait for a network request and process it
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock);
            if (stop_server) {
                break;
            }
            processRequest(getNextClientID());
        }
    }

    int getNextClientID() {
        // Simulate obtaining the next client ID from the network
        static int clientID = 1;
        return clientID++;
    }

    void startServer() {
        for (int i = 0; i < THREAD_COUNT; ++i) {
            thread_pool.emplace_back(&Server::handleRequests, this);
        }
    }

    void stopServer() {
        stop_server = true;
        cv.notify_all(); // Notify all threads to stop
        for (auto& thread : thread_pool) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }
};

