```cpp
#include <mutex>
#include <condition_variable>

class MultiThreadedLock {
private:
    std::mutex mtx;
    std::condition_variable cv;
    int numReaders;
    bool isWriter;

public:
    MultiThreadedLock() : numReaders(0), isWriter(false) {}

    bool tryLockRead() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !isWriter; });
        ++numReaders;
        return true;
    }

    bool tryLockWrite() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return numReaders == 0 && !isWriter; });
        isWriter = true;
        return true;
    }

    int lockStatus() const {
        std::lock_guard<std::mutex> lock(mtx);
        if (isWriter) {
            return -1; // Write lock acquired
        } else {
            return numReaders; // Number of read locks acquired
        }
    }

    void unlockRead() {
        std::lock_guard<std::mutex> lock(mtx);
        if (numReaders > 0) {
            --numReaders;
            if (numReaders == 0) {
                cv.notify_all();
            }
        }
    }

    void unlockWrite() {
        std::lock_guard<std::mutex> lock(mtx);
        isWriter = false;
        cv.notify_all();
    }
};
```

In this solution, a `std::mutex` and a `std::condition_variable` are used to implement the locking mechanism. The `tryLockRead()` and `tryLockWrite()` functions use the condition variable to wait until the requested lock can be acquired, and the `unlockRead()` and `unlockWrite()` functions release the locks and notify waiting threads. The `lockStatus()` function provides the current lock status based on the number of read locks acquired and the presence of a write lock. This implementation ensures that the locking mechanism satisfies the specified requirements and provides thread safety.

```cpp
#include <unordered_set>
#include <cmath>

class Solution {
public:
    bool checkPerfectNumber(int num) {
        if (num <= 1) {
            return false;
        }

        int sum = 1;  // 1 is always a proper divisor
        int sqrtNum = sqrt(num);
        for (int i = 2; i <= sqrtNum; i++) {
            if (num % i == 0) {
                sum += i;
                if (i != num / i) {
                    sum += num / i;
                }
            }
        }

        return sum == num;
    }
};
```
In the `checkPerfectNumber` method, we first handle the base case where `num` is less than or equal to 1, in which case it cannot be a perfect number. Then, we iterate through all numbers from 2 to the square root of `num` to find its proper divisors. For each divisor found, we add it to the `sum` and also add its complement divisor if it's not the same. Finally, we compare the `sum` with the original `num` and return `true` if they are equal, indicating that `num` is a perfect number, and `false` otherwise.

