```cpp
// Created By: <NAME>
// Date: --

#include <iostream>
#include <stdexcept>

class StackArray {
private:
    int *arr;
    int topIndex;
    int capacity;

public:
    // Parameterized Constructor
    StackArray(int size) {
        // Initialize the stack with the given capacity
        capacity = size;
        arr = new int[capacity];
        topIndex = -1;
    }

    // Add an element to the top of the stack
    void push(int val) {
        if (topIndex == capacity - 1) {
            throw std::overflow_error("Stack overflow");
        }
        arr[++topIndex] = val;
    }

    // Remove the element from the top of the stack and return its value
    int pop() {
        if (topIndex == -1) {
            throw std::underflow_error("Stack underflow");
        }
        return arr[topIndex--];
    }

    // Return the value of the top element without removing it
    int top() {
        if (topIndex == -1) {
            throw std::underflow_error("Stack is empty");
        }
        return arr[topIndex];
    }

    // Return true if the stack is empty, false otherwise
    bool isEmpty() {
        return topIndex == -1;
    }
};

int main() {
    StackArray stack(5);
    stack.push(1);
    stack.push(2);
    stack.push(3);
    std::cout << stack.pop() << std::endl; // Output: 3
    std::cout << stack.top() << std::endl; // Output: 2
    std::cout << stack.isEmpty() << std::endl; // Output: 0 (false)
    return 0;
}
```

In the solution, the `push` method checks for stack overflow before adding an element to the stack. The `pop` method checks for stack underflow before removing an element from the stack. The `top` method returns the value of the top element without removing it and also checks for stack underflow. The `isEmpty` method checks if the stack is empty by examining the top index.

