        auto [x, y] = q.front();
        q.pop();

        for (int k = 0; k < 4; ++k) {
            int i = x, j = y;
            while (i >= 0 && i < m && j >= 0 && j < n && maze[i][j] == 0) {
                i += dy[k];
                j += dy[k^1];
            }
            i -= dy[k];
            j -= dy[k^1];
            if (dist[i][j] == -1 || dist[x][y] + abs(i - x) + abs(j - y) < dist[i][j]) {
                dist[i][j] = dist[x][y] + abs(i - x) + abs(j - y);
                q.push({i, j});
            }
        }
    }

    return dist[m - 1][n - 1];
}
